test('setLinks swaps in real URLs for pages and workspace screens, then restores', () => {
  CB.setLinks({ page: (p) => '/' + p, view: (v) => '/app/' + v });
  assert.match(html(h(CB.PricingPage, {})), /href="\/pricing" aria-current="page"/);
  assert.match(html(h(CB.AuthPage, { mode: 'signin' })), /href="\/reset"/);
  assert.match(html(h(CB.Workspace, { view: 'money' })), /href="\/app\/money" aria-current="page"/);
  assert.match(html(h(CB.Workspace, { view: 'overview' })), /href="\/app\/settings"/);
  CB.setLinks({ page: 'not a function' });
  assert.match(html(h(CB.PricingPage, {})), /href="\/pricing"/, 'a bad resolver is ignored');
  CB.setLinks({ page: (p) => '#' + p, view: (v) => '#' + v });
  assert.match(html(h(CB.PricingPage, {})), /href="#pricing"/);
});

